export type WorkContextBinding = {
  version: 1;
  id: string;
  status: "active" | "superseded";
  host: string;
  session_id: string;
  bound_at: string;
  last_seen_at: string;
  expires_at: string;
  collaboration_space: WorkspaceRef;
